print('manifest',hashlib.sha256(mb).hexdigest(),'parent',m['parentSubjectSha256'],'files',len(m['files']),'bad',bad,'unlisted',unl)
def tree(root):
    out={}
    for d,_,fs in os.walk(root):
        for x in fs:
            p=os.path.join(d,x); out[os.path.relpath(p,root)]=sha(p)
    return out
a=tree(V2+'output'); b=tree(V3+'output')
