class PayloadExchange:
    """Runs a protocol3 exchange (ref/protocol3.py reads the published table) and applies the prose-owned FactBatch payload law at
    every FactBatch that reaches row matching in ANALYZING. A refused payload faults the exchange with the provider-return public
    route (operational-failed PROVIDER.PROTOCOL_VIOLATION). The payload rule is recorded like the s9.1 Hello echo rule. Every later
    frame is absorbed under the table's first pre-match law."""

    def __init__(self, machine, retained, shape, host):
        self.m, self.retained, self.shape, self.host = machine, retained, shape, host

    def run(self, events):
        trace, states, payloads, request_faults = [], [], [], []
        hello_caps = ack_caps = analyze = None
        stream, fault_state = {}, None
        for i, e in enumerate(events):
            if fault_state is not None:
                trace.append({"frame": e["frame"], "rule": "FAULT-absorb", "phase": "FAULT"})
                states.append(copy.copy(fault_state))
                continue
            before = self.m.run(events[:i])["state"]
            if e["frame"] == "Hello":
                hello_caps = e.get("expectedCapabilities")
            if e["frame"] == "HelloAck":
                ack_caps = e.get("capabilities")
            if e["frame"] == "Analyze" and "analyze" in e:
                analyze = e["analyze"]
                request_faults = analyze_request_faults(analyze, self.shape, self.retained, e["stageCount"])
            if e["frame"] == "FactBatch" and "payload" in e:
                if before["phase"] != "ANALYZING" or analyze is None:
                    payloads.append({"step": i, "payloadChecked": False,
                                     "reason": f"FactBatch arrives in phase {before['phase']}; a pre-match law or the table decides before payload validation"})
                else:
                    request = stage_request(analyze, self.shape, before["stageIndex"])
                    dispatch = derive_dispatch(self.retained, request, stream) if e.get("dispatch", "derive") == "derive" else e["dispatch"]
                    res = buffer_fact_batch_occupancy(e["payload"], hello_caps, ack_caps, dispatch, self.retained, request, self.host)
                    payloads.append({"step": i, "payloadChecked": True, "request": request, **res})
                    if res["result"] == "REFUSE":
                        fault_state = dict(before, phase="FAULT")
                        trace.append({"frame": "FactBatch", "rule": f"payload:fact-batch-refused({res['firstRefusal']})", "phase": "FAULT"})
                        states.append(copy.copy(fault_state))
                        continue
                    advance(stream, e["payload"])
            step = self.m.run(events[:i + 1])
            trace.append(step["trace"][-1])
            states.append(step["state"])
        final = copy.copy(fault_state) if fault_state is not None else self.m.run(events)["state"]
        return {"trace": trace, "states": states, "state": final, "payloads": payloads, "analyzeRequestFaults": request_faults,
                "negotiated": negotiated(hello_caps, ack_caps)}

